	/**  대상 신호 id (입력 cards.json과 매칭). */
	id: string,
	/**  표시용 카드 제목 (UI 패널 — 입력 신호에서 채워 돌려준다). */
	title?: string | null,
	/**  제안 사분면 힌트(닫힌 enum). 자동 분류 아님. */
	suggestedQuadrant?: Quadrant | null,
