export type DiffMode = 
/**  미커밋 워킹트리 diff (워킹트리 vs index, unstaged). */
"working" | 
/**  index diff (staged, index vs HEAD). */
"staged" | 
/**  `git diff <base>...<head>` (3-dot, merge-base 기준). */
"vs_base" | 
/**  임의 두 ref 직접 비교 (`git diff <base> <head>`). */
"branch_branch";

