/**
 *  pending_calendar_writes 행. payload_json은 op별 자유 형태(create=title/start/duration_min,
 *  patch=start/duration_min, delete={}; staged=true는 워커가 skip — cross-cal Acceptance 게이트).
 */
export type PendingWrite = {
	id: number,
	/**  create | patch | delete. */
	kind: string,
	/**  signal | routine_check | event. */
	target_kind: string,
	/**  signal id, `routine_id|date`(routine_check), 또는 `calendar_id|event_id`(event). */
	target_id: string,
	calendar_id: string,
	event_id: string | null,
	payload_json: string,
	attempts: number,
	next_attempt_at: string,
	last_error: string | null,
	created_at: string,
};

/**  외부 API ping 결과 (read-only). 토큰 본문은 포함하지 않는다. */
