/**
 *  PR Radar 한 항목 (프런트 표시용). ambient 상태라 매 폴링마다 GitHub에서 새로 도출된다.
 *  토큰 본문은 절대 담기지 않는다(INVARIANT). specta i64/u64 export 금지 → number/ageDays는 u32.
 */
export type PrRadarItem = {
	repoFullName: string,
	number: number,
	title: string,
	url: string,
	authorLogin: string,
	bucket: ReadinessBucket,
	ci: CiStatus,
	hasConflict: boolean,
	isDraft: boolean,
	/**  수동 self-check 로컬 상태 (GitHub 아님). */
	selfChecked: boolean,
	/**  경과일 (updated_at 기준, 0 = 오늘 갱신). */
	ageDays: number,
	projectId: string,
	/**  댓글 수 (comments + review_comments). open PR만 채움, merged는 0. */
	commentCount: number,
	/**  댓글이 SUSPICIOUS_COMMENT_THRESHOLD 초과인지(시각 경고 힌트). */
	isSuspicious: boolean,
	/**  Inbox에 읽지 않은 alert가 있는지. */
	hasUnreadAlert: boolean,
	/**  threshold/패턴상 critical alert인지. */
	hasCriticalAlert: boolean,
	/**  AI 분석이 필요한 상태로 flag됐는지. */
	aiFlagged: boolean,
};

export type PrRadarSettings = {
	/**  Poll interval in minutes. Default 10. */
	pollIntervalMinutes: number,
	/**  Comment count threshold for Inbox escalation. Default 10. */
	commentAlertThreshold: number,
	/**  Conflict pattern detection creates critical Inbox alerts when enabled. */
	conflictAlertsEnabled: boolean,
	/**  If true, eligible alert rows are marked as AI analysis candidates. */
	aiAutoAnalysisEnabled: boolean,
};

/**
 *  PR self-check 초안 Proposal (codex 산출물, draft). 사람이 accept하면 로컬에 반영(제출은 수동).
 *  serde default로 codex가 일부 필드를 누락해도 관용한다(스키마-관용 — Phase 7 선례).
 */
export type PrSelfCheckProposal = {
	/**  PR 설명 초안 (사람이 수동 제출). */
	summary?: string,
	/**  self-check 체크리스트 항목. */
	selfChecks?: SelfCheckItem[],
	/**  스크린샷이 필요한 변경 (UI 등). */
	screenshotsNeeded?: string[],
	/**  마이그레이션/배포 주의 노트. */
	migrationNotes?: string[],
};

