/**  아이젠하워 사분면 (사람 결정값). 카드는 항상 `Unclassified`로 진입한다 (INVARIANT #1). */
export type Quadrant = "q1_do_now" | "q2_schedule" | "q3_quick_contain" | "q4_drop" | "unclassified";

/**  readiness 버킷 (PR Radar 자기 뷰의 분류 — 매트릭스 결정 레일과 별개, INVARIANT #4). */
