	present: boolean,
	/**  이 provider에서 발견한 스킬 수(specta는 i64 미지원 → i32; 스킬 수는 작다). */
	skillCount: number,
	/**  주 루트 절대경로(표시 전용 — 로그 금지). 동일 provider 다중 루트면 첫 루트. */
